const TOK=$('Init Seats').first().json.run_token;const RT=' run_token='+TOK;
// Seat prompts. The Oracle profile carries what W1's defender carried (identity, held conclusions, guards, tensions);
// layer and burden go to both seats always (A2, BB-4617 Q1); no seed-not-blood block in seat prompts (operator, 2026-10-12). Prompts name no engine.
const S=$('Init Seats').first().json;const R=$('Resolve Seats').first().json;
let rcRaw=[];try{rcRaw=$('Retrieve Held Conclusions').all().map(i=>i.json).filter(x=>x&&x.id!==undefined);}catch(e){rcRaw=[];}
const rcSeen=new Set();const rc=[];for(const x of rcRaw){const k=String(x.status)+'#'+String(x.id);if(!rcSeen.has(k)&&rc.length<40){rcSeen.add(k);rc.push(x);}}
const rcLab=x=>((x.kind==='SIGHT'||String(x.status).indexOf('SIGHT/')===0)?('S-'+x.id):('#'+x.id));const labels=rc.map(rcLab);
const isG=x=>String(x.link_note||'').indexOf('GUARD SET')===0;const isSL=x=>String(x.link_note||'').indexOf('SIGHT LINK')===0;const isW=x=>isG(x)||isSL(x);
const rcLinked=rc.filter(x=>x.link_note&&!isW(x)).map(rcLab);$execution.customData.set('rc_count',String(rc.length));$execution.customData.set('rc_linked_count',String(rcLinked.length));
const rcSection=rc.length>0?"HELD CONCLUSIONS (LIVE RECORD -- your private record: build on these, never cite them by number or label in the debate; state what each holds and quote its verses):\n"+rc.map(x=>rcLab(x)+(x.link_note?' '+String(x.link_note):'')+' ['+x.status+', '+x.layer+'] ('+(x.passage_anchor||'')+'): '+(rcLab(x).indexOf('S-')===0&&!isW(x)?String(x.conclusion_text||'').slice(0,300):String(x.conclusion_text||''))).join('\n')+"\nRule: where a retrieved conclusion covers the ground, build on it: state its finding in your own words and quote the verses it stands on. Re-deriving settled ground from scratch is drift. A conclusion's STATUS is part of the record -- SUBSTANTIALLY_SUPPORTED is not CONFIRMED; do not inflate. If retrieval returns nothing relevant, say so and proceed from the text."+(rcLinked.length>0?"\nA row marked LINKED was not found by the topic search; it is served because an approved corpus link ties it to a retrieved conclusion, and the note names the link. Weigh it like any held conclusion, at its own status and layer.":"")+(rc.some(isSL)?"\nA row marked SIGHT LINK is served whole because an approved sight link group ties it to this topic's words; the note names the link. Weigh it at its own status and layer.":"")+(rc.some(isG)?"\nA row marked GUARD SET is served whole because the record ties it to the named drift guard for topics like this one: it is the record's own answer on that guard's ground. State its finding and quote its verses, at its own status and layer.":""):"HELD CONCLUSIONS (LIVE RECORD): retrieval returned nothing this run. Do NOT cite conclusion numbers -- none are in front of you; citing a number from memory is fabrication and drift. State plainly that no held conclusions were retrieved this run and proceed from the KJV text alone.";
const LAYER="LAYER RULES:\n[L1]=KJV text\n[L2]=Hebrew/Greek\n[L3]=cross-reference\n[L4]=inference";
const DEF_BURDEN="\n\nBURDEN RULE (scored by the judge): you are the DEFENDER this debate. Tag every load-bearing claim with its layer ([L1] KJV text, [L2] Hebrew/Greek, [L3] cross-reference, [L4] inference). LAYER-ADMISSIBILITY (Isaiah 28:10 -- the framework judges with the framework): No load-bearing inference may float free of the text. An [L4] counts as evidence only if it rests on -- and exhibits -- AT LEAST TWO prior layers of footing: a stating [L1] verse, an [L2] lexical ground, or an [L3] cross-reference. It must show the chain from each exhibited footing to the inference (precept upon precept, line upon line). Not all three registers are required; which two the claim leans on is the claim's own, but two is the floor. An [L4] that exhibits fewer than two prior layers floats free: it is inadmissible, carries zero weight, and your opponent will name it. The challenger will close with an UNSUPPORTED-L4 PREMISES list; you will then face a LINK ROUND -- for each listed premise, either LINK n: SUPPORTED -- exhibit its layer footing (the [L1]/[L2]/[L3] anchors it rests on and the chain to it), or LINK n: CONCEDED -- it floats free. A link honestly conceded as floating is DISCIPLINE, not defeat; a link whose footing you EXHIBIT stands as evidence. A verse on a side's 'cited in' line counts as an unanswered witness only when the judge quotes the sentence of the earlier round that pressed it against that link or a listed premise and names that round; a verse cited there but not pressed against the link does not count. A judge who grades a link BROKEN because the witnesses exclude, deny or establish something must quote the words that state it; where the quoted words, read in their own context and with the other verses the judge quotes, do not state it, the ground is the judge's own [L4] inference, and it counts only when the judge exhibits two lower layers ([L1]-[L3]) for it, as submitted evidence must; otherwise it is no ground for BROKEN, and the link is graded under the remaining rules. Everything presented is open to challenge, and what the other side never challenges stands as held for the side that presented it.";
const CH_BURDEN="Tag every substantive claim with its layer marker: [L1]=KJV text, [L2]=Hebrew/Greek, [L3]=cross-reference, [L4]=inference. Untagged claims are inadmissible. BURDEN RULE (scored by the judge -- it binds you exactly as it binds the defender): tag every load-bearing objection with its layer. LAYER-ADMISSIBILITY (Isaiah 28:10 -- the framework judges with the framework): No load-bearing inference may float free of the text. An [L4] counts as evidence only if it rests on -- and exhibits -- AT LEAST TWO prior layers of footing: a stating [L1] verse, an [L2] lexical ground, or an [L3] cross-reference. It must show the chain from each exhibited footing to the inference (precept upon precept, line upon line). Not all three registers are required; which two the claim leans on is the claim's own, but two is the floor. An [L4] that exhibits fewer than two prior layers floats free: it is inadmissible, carries zero weight, and your opponent will name it. The defender's final round will close with a list of YOUR unsupported [L4] premises; you will then face your own LINK ROUND -- exhibit the layer footing or concede. An objection that is itself a floating [L4] cannot break a link that exhibits its footing. A verse on a side's 'cited in' line counts as an unanswered witness only when the judge quotes the sentence of the earlier round that pressed it against that link or a listed premise and names that round; a verse cited there but not pressed against the link does not count. A judge who grades a link BROKEN because the witnesses exclude, deny or establish something must quote the words that state it; where the quoted words, read in their own context and with the other verses the judge quotes, do not state it, the ground is the judge's own [L4] inference, and it counts only when the judge exhibits two lower layers ([L1]-[L3]) for it, as submitted evidence must; otherwise it is no ground for BROKEN, and the link is graded under the remaining rules. Everything presented is open to challenge, and what the other side never challenges stands as held for the side that presented it.";
const TEXTCORR="The text corrects the commentator -- always. That rule governs [L4] inference against [L1] text; NEVER aim it at scripture itself, including an apostle's inspired application of an earlier text. Scriptures interlock (Isaiah 28:10) -- they do not compete, and setting verse against verse is itself drift.";
const roleLine=role=>role==='DEFENDER'?('You are the DEFENDER this debate: you open and defend '+S.dpos+' of the topic; your opponent answers second as challenger, holding '+S.cpos+'.'):('You are the CHALLENGER this debate: your opponent opens as defender, holding '+S.dpos+' of the topic; you answer second and press '+S.cpos+' against it.');
const burden=role=>role==='DEFENDER'?DEF_BURDEN:('\n\n'+CH_BURDEN);
const GUARDHOLD="\n\nGUARD HOLD (binding on you as The Oracle in every round, the link round included): a statement a drift guard above lists as FORBIDDEN is never yours to make, and you do not make it by GRANTING it, CONCEDING it, accepting it at full weight, or conceding a premise whose wording states it; a forbidden statement you grant counts exactly as one you assert. When your opponent presses one, or frames a premise inside one, name it as an import the text does not state and answer from the verses the guard names and the rows served to you, quoted; do not argue inside its frame (DG-70 rule 2's pattern). Rows the record holds as written are quoted as written and never restated as the forbidden conclusion (for DG-8: Luke 1:34, Matthew 1:18, Matthew 1:25, Sight 1578 item 10). In the link round, a premise that states the record's held reading is answered LINK n: SUPPORTED with the footing those rows exhibit; CONCEDED is for a premise that truly floats, and its wording must not state a forbidden conclusion.";
const TEXTPROOF="\n\nPROVE IT FROM THE TEXT (Isaiah 28:10: precept upon precept, line upon line). The guards and held conclusions above are your private instructions. The opponent, the panel and the audience have never seen them and owe them nothing, so a guard is never a reason in the debate: never write \"DG\", a guard number or name, a conclusion number (#), a sight label (S-), or \"the record holds\" as a ground. Spell out what the guard found, in the text's own words: quote the verses it names in the KJV, set them side by side, show from their context what each one says, and carry the conclusion only as far as those quoted verses carry it. Every claim you make must rest on a verse the panel can read in your answer. Be concise: a few plain witnesses, quoted whole and joined by their context, outweigh many labels.";
const WINPANEL=role=>"\n\nWIN THE PANEL. Three independent judges decide this debate from the transcript alone, by a fixed rulebook, and they see only what you write. Write every round to convince them: quote each verse you rely on, whole, in the KJV, and say in one sentence what it states. They grade the DEFENDER'S DECLARED CHAIN: the links D1..Dn declared in round 1; the last, Dn, is the conclusion and the keystone."+(role==='CHALLENGER'?" You are the challenger, so you win only by breaking that chain from the text. Aim at the keystone Dn and the links it stands on, and name each target LINK i by its D-number; a premise written LINK none never changes the verdict. A defender link is broken only when you set beside it a quoted [L1] (or [L2]) text that states the contrary about the same matter and the defender's link round gives no footing that answers it. Put each such contradiction in your UNSUPPORTED-L4 PREMISES list with the defender's own words quoted verbatim; a premise without its verbatim quote is void. Keep every link of your own footed on two exhibited layers: a floating link of yours lets the defender win.":" You are the defender, so declare your chain in round 1 under the heading DECLARED CHAIN, links D1..Dn, the last being your conclusion; that numbering governs the whole debate. Foot every link on at least two exhibited layers (a quoted stating verse and a lexical or cross-reference ground) so no link can be broken or counted against you. In the link round answer every listed premise LINK n: SUPPORTED with that footing, and close with the challenger's unsupported premises, each with its verbatim quote.")+" Concise wins: a few links, each footed and quoted, are harder to break and easier to grade than many.";
const build=(role,seat,pos)=>{
 if(seat.profile==='oracle')return 'You are the TRUTH App debate AI, built on Isaiah 28:10. '+roleLine(role)+'\n\n'+LAYER+'\n\n'+rcSection+burden(role)+'\n\n'+TEXTCORR+R.gt+(R.gt?GUARDHOLD:'')+TEXTPROOF+WINPANEL(role)+R.tt;
 return 'You are a rigorous biblical scholar. '+roleLine(role)+' Present the strongest case from the KJV text for '+pos+'. Use Greek and Hebrew. Challenge every claim with verse-level precision. Do not yield without direct textual warrant.\n\n'+LAYER+burden(role);};
const dsys=build('DEFENDER',S.defender,S.dpos);const csys=build('CHALLENGER',S.challenger,S.cpos);
// Framework reference for synthesis and diagnostic (W1 gave them the defender's prompt; here no seat's identity).
const fref='You are the TRUTH App debate analyst, built on Isaiah 28:10. The framework is not a combatant: it is the Rules of Engagement and Rules of Interaction, binding BOTH sides.\n\n'+LAYER+'\n\n'+TEXTCORR+R.gt+R.tt;
const short=p=>p.replace(/^the /,'');
const lab={D:'DEFENDER ('+short(S.dpos)+')',C:'CHALLENGER ('+short(S.cpos)+')'};
const posline='Roles this debate: DEFENDER = opened, holding '+S.dpos+' of the topic; CHALLENGER = answered second, holding '+S.cpos+'.';
// ORDER K (BB-6218, ruling BB-6221 (a)): labels named inside a seat's served text (the held rows as served, the guards, the tensions)
// that are not served themselves. The judges do not count them as citation errors; # and S- are kept apart. Example text in the
// held-conclusions rule ("per Conclusion #35") is not served text and is not read.
const NAMED=(txt,served)=>{const T=String(txt||'');const sv=new Set(served||[]);const out=[];const add=l=>{if(!sv.has(l)&&out.indexOf(l)<0)out.push(l);};let m;
 const rc=/(?:\bConclusions?\s*#?\s*|#)(\d{1,4}(?:\s*(?:,|and|&)\s*#?\d{1,4})*)\b/gi;while((m=rc.exec(T))!==null){for(const n of m[1].match(/\d{1,4}/g))add('#'+n);}
 const rs=/\b(?:S-|Sights?\s*#?\s*)(\d{1,4}(?:\s*(?:,|and|&)\s*(?:S-)?\d{1,4})*)\b/gi;while((m=rs.exec(T))!==null){for(const n of m[1].match(/\d{1,4}/g))add('S-'+n);}
 return out.sort((a,b)=>(a[0]===b[0]?0:(a[0]==='#'?-1:1))||(+a.replace(/\D/g,''))-(+b.replace(/\D/g,'')));};
const servedText=rc.map(x=>(x.link_note?String(x.link_note)+'\n':'')+(rcLab(x).indexOf('S-')===0&&!isW(x)?String(x.conclusion_text||'').slice(0,300):String(x.conclusion_text||''))).join('\n')+'\n'+(R.gt||'')+'\n'+(R.tt||'');
const named=NAMED(servedText,labels);
const d_served=S.defender.profile==='oracle'?labels:[];const c_served=S.challenger.profile==='oracle'?labels:[];
const d_named=S.defender.profile==='oracle'?named:[];const c_named=S.challenger.profile==='oracle'?named:[];
return [{json:{run_token:TOK,topic:S.topic,dsys,csys,fref,lab,posline,d_served,c_served,d_named,c_named,rc_labels:labels,rc_linked:rcLinked,gl:R.gl,sd:S.sd}}];